const root = $input.first().json || {};
const body = Array.isArray(root) ? (root[0]?.body || root[0]) : (root.body || root);
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};
const instanceName = body.instance || data.instance || '';
const instanceId = data.instanceId || null;
const serverUrl = body.server_url || body.serverUrl || $env.EVO_DEFAULT_SERVER_URL || '';
const event = body.event || '';
const remoteJid = key.remoteJid || key.remoteJidAlt || '';
const senderIdentifier = String(remoteJid || '').split('@')[0] || '';
const fromMe = Boolean(key.fromMe);
const providerMessageId = key.id || null;
const pushName = data.pushName || 'Cliente';
const messageTimestamp = data.messageTimestamp || null;
let messageType = data.messageType || 'unknown';
let contentText = message.conversation || message.extendedTextMessage?.text || message.imageMessage?.caption || message.videoMessage?.caption || message.documentMessage?.caption || '';
let captionText = message.imageMessage?.caption || message.videoMessage?.caption || message.documentMessage?.caption || null;
let mediaType = null, mediaUrl = null, mediaMimeType = null, mediaFileName = null;
if (message.audioMessage) { mediaType='audio'; mediaUrl=message.audioMessage.url||null; mediaMimeType=message.audioMessage.mimetype||message.audioMessage.mimeType||'audio/ogg'; }
else if (message.imageMessage) { mediaType='image'; mediaUrl=message.imageMessage.url||null; mediaMimeType=message.imageMessage.mimetype||message.imageMessage.mimeType||'image/jpeg'; }
else if (message.documentMessage) { mediaType='document'; mediaUrl=message.documentMessage.url||null; mediaMimeType=message.documentMessage.mimetype||message.documentMessage.mimeType||null; mediaFileName=message.documentMessage.fileName||null; }
else if (message.videoMessage) { mediaType='video'; mediaUrl=message.videoMessage.url||null; mediaMimeType=message.videoMessage.mimetype||message.videoMessage.mimeType||'video/mp4'; }
else if (message.stickerMessage) { mediaType='sticker'; mediaUrl=message.stickerMessage.url||null; mediaMimeType=message.stickerMessage.mimetype||message.stickerMessage.mimeType||'image/webp'; }
let routeType = mediaType || 'text';
return [{ json: { provider:'evolution_api', event, instance_name:instanceName, instance_id:instanceId, server_url:serverUrl, remote_jid:remoteJid, remote_jid_alt:key.remoteJidAlt||null, sender_identifier:senderIdentifier, sender_name:pushName, from_me:fromMe, provider_message_id:providerMessageId, message_type:messageType, route_type:routeType, content_text:contentText, caption_text:captionText, message_timestamp:messageTimestamp, has_media:Boolean(mediaType), media_type:mediaType, media_url:mediaUrl, media_mime_type:mediaMimeType, media_file_name:mediaFileName, raw_payload:body } }];

